<?php
session_start();
require __DIR__ . '/config.php';
require_admin();
$pdo = db();
$stats = [
 'links' => (int)$pdo->query("SELECT COUNT(*) FROM tracking_links")->fetchColumn(),
 'active' => (int)$pdo->query("SELECT COUNT(*) FROM tracking_links WHERE is_active=1")->fetchColumn(),
 'reports' => (int)$pdo->query("SELECT COUNT(*) FROM location_reports")->fetchColumn(),
 'clicks' => (int)$pdo->query("SELECT COALESCE(SUM(click_count),0) FROM tracking_links")->fetchColumn()
];
$links = $pdo->query("SELECT l.*, (SELECT COUNT(*) FROM location_reports r WHERE r.link_id=l.id) report_count, (SELECT MAX(r.reported_at) FROM location_reports r WHERE r.link_id=l.id) last_report FROM tracking_links l ORDER BY l.created_at DESC")->fetchAll();
$recent = $pdo->query("SELECT r.*, l.label, l.token FROM location_reports r JOIN tracking_links l ON l.id=r.link_id ORDER BY r.reported_at DESC LIMIT 8")->fetchAll();
$flash = get_flash();
?>
