<?php if (!$recent): ?><div class="mini-empty"><span>⌖</span><div><b>No location reports yet</b><p>Reports will appear here when visitors choose to share their location.</p></div></div><?php else: ?><div class="report-list"><?php foreach ($recent as $r): ?><div class="report-row"><div class="report-pin">⌖</div><div class="report-detail"><b><?=e($r['label'])?></b><small><?=e($r['latitude'])?>, <?=e($r['longitude'])?> · Accuracy <?=e($r['accuracy_meters'] === null ? 'unknown' : round((float)$r['accuracy_meters']).' m')?></small></div><div class="report-time"><?=e(date('M j, g:i a',strtotime($r['reported_at'])))?></div><a class="map-link" target="_blank" rel="noopener" href="https://www.google.com/maps?q=<?=rawurlencode($r['latitude'].','.$r['longitude'])?>">Open map ↗</a></div><?php endforeach; ?></div><?php endif; ?></section>
